import http from 'node:http'
import fs from 'node:fs'
import path from 'node:path'
import { createHash } from 'node:crypto'

const root = fs.realpathSync(process.argv[2])
const port = 18146
// Disabled unless the owner explicitly opts this task-only loopback server in.
const faultFile = process.env.YUNLEFUN_NATIVE_GAME_FAULT_CONTROL
if (faultFile && (!path.resolve(faultFile).startsWith('/tmp/yunle-native-games.uGZuY9/') || !faultFile.endsWith('.json'))) throw Error('Fault control must be task-owned /tmp JSON')
const scenarios = new Set(['healthy', 'manifest503', 'badDigest', 'slowPrepare', 'versionB'])
let counterKey = ''
let counts = { manifestRequests: 0, baseAssetRequests: 0, slowResourceRequests: 0 }
function faultState() {
  let state = { schemaVersion: 1, runID: null, scenario: 'healthy', gameID: 'gomoku' }
  if (faultFile) {
    try {
      const saved = JSON.parse(fs.readFileSync(faultFile, 'utf8'))
      if (saved.schemaVersion === 1 && scenarios.has(saved.scenario) && saved.gameID === 'gomoku'
          && /^[a-f0-9-]{36}$/i.test(saved.runID) && Date.now() - saved.updatedAt < 10 * 60 * 1000) state = saved
    } catch {}
  }
  const key = `${state.runID}:${state.scenario}`
  if (counterKey !== key) { counterKey = key; counts = { manifestRequests: 0, baseAssetRequests: 0, slowResourceRequests: 0 } }
  return state
}
function jsonReply(response, status, value) {
  const bytes = Buffer.from(JSON.stringify(value))
  response.writeHead(status, { 'content-type': 'application/json', 'content-length': bytes.length, 'cache-control': 'no-store' }).end(bytes)
}
function faultResource(state) {
  const bytes = Buffer.from(`Native resource receipt fault fixture ${state.runID}\n`)
  const pathname = `/games/gomoku/native-fault-${state.runID.toLowerCase()}.bin`
  return { bytes, pathname, record: { url: `https://play.yunle.fun${pathname}`, sha256: createHash('sha256').update(bytes).digest('hex'), byteCount: bytes.length, contentType: 'application/octet-stream', required: true } }
}
const types = {
  '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.mjs': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8', '.json': 'application/json; charset=utf-8', '.wasm': 'application/wasm',
  '.svg': 'image/svg+xml', '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.webp': 'image/webp',
  '.avif': 'image/avif', '.ico': 'image/x-icon', '.woff': 'font/woff', '.woff2': 'font/woff2', '.ttf': 'font/ttf',
  '.glb': 'model/gltf-binary', '.gltf': 'model/gltf+json', '.bin': 'application/octet-stream',
  '.mp3': 'audio/mpeg', '.ogg': 'audio/ogg', '.wav': 'audio/wav', '.mp4': 'video/mp4', '.webm': 'video/webm',
}
const server = http.createServer((request, response) => {
  let pathname
  try { pathname = decodeURIComponent(new URL(request.url, 'http://127.0.0.1').pathname) }
  catch { response.writeHead(400).end(); return }
  const state = faultState()
  if (faultFile && pathname === '/__native-game-faults/control') {
    if (request.socket.remoteAddress !== '127.0.0.1' || request.headers['x-yunle-native-fault-fixture'] !== 'resource-cache-v1'
        || (request.headers.origin && request.headers.origin !== 'http://127.0.0.1:18146')) { jsonReply(response, 403, { ok: false }); return }
    if (request.method === 'GET') { jsonReply(response, 200, { ...state, enabled: true, counts }); return }
    if (request.method !== 'POST' || request.headers['content-type'] !== 'application/json') { jsonReply(response, 405, { ok: false }); return }
    let data = ''
    request.on('data', chunk => { data += chunk; if (data.length > 2048) request.destroy() })
    request.on('end', () => {
      try {
        const input = JSON.parse(data)
        if (input.schemaVersion !== 1 || input.gameID !== 'gomoku' || !scenarios.has(input.scenario)
            || !/^[a-f0-9-]{36}$/i.test(input.runID)) { jsonReply(response, 400, { ok: false }); return }
        if (state.scenario !== 'healthy' && state.runID !== input.runID) { jsonReply(response, 409, { ok: false }); return }
        fs.writeFileSync(faultFile, JSON.stringify({ schemaVersion: 1, runID: input.runID, scenario: input.scenario, gameID: input.gameID, updatedAt: Date.now() }) + '\n')
        jsonReply(response, 200, { ...faultState(), enabled: true, counts })
      } catch { jsonReply(response, 400, { ok: false }) }
    })
    return
  }
  if (!['GET', 'HEAD'].includes(request.method)) { response.writeHead(405).end(); return }
  if (faultFile && pathname.startsWith('/_nuxt/')) counts.baseAssetRequests++
  if (faultFile && pathname === '/native/resources/gomoku-v1.json') {
    counts.manifestRequests++
    if (state.scenario === 'manifest503') { jsonReply(response, 503, { error: 'test-only manifest outage' }); return }
    if (state.scenario !== 'healthy') {
      const manifest = JSON.parse(fs.readFileSync(path.join(root, 'native/resources/gomoku-v1.json'), 'utf8'))
      if (state.scenario === 'badDigest') manifest.resources[0].sha256 = '0'.repeat(64)
      else {
        const resource = faultResource(state)
        manifest.resources.push(resource.record)
        manifest.totalBytes += resource.bytes.length
      }
      manifest.version = createHash('sha256').update(JSON.stringify(manifest.resources)).digest('hex')
      const bytes = Buffer.from(JSON.stringify(manifest))
      response.writeHead(200, { 'content-type': 'application/json', 'content-length': bytes.length, 'cache-control': 'public, max-age=60' })
      response.end(request.method === 'HEAD' ? undefined : bytes)
      return
    }
  }
  if (faultFile && state.runID) {
    const resource = faultResource(state)
    if (pathname === resource.pathname) {
      const send = () => {
        if (response.destroyed) return
        response.writeHead(200, { 'content-type': 'application/octet-stream', 'content-length': resource.bytes.length, 'cache-control': 'public, max-age=31536000, immutable' })
        response.end(request.method === 'HEAD' ? undefined : resource.bytes)
      }
      if (state.scenario === 'slowPrepare') {
        counts.slowResourceRequests++
        const delay = setTimeout(send, 12000)
        response.on('close', () => clearTimeout(delay))
      } else send()
      return
    }
  }
  let file = path.resolve(root, '.' + pathname)
  if (!file.startsWith(root + path.sep) && file !== root) { response.writeHead(403).end(); return }
  try {
    if (fs.statSync(file).isDirectory()) file = path.join(file, 'index.html')
  } catch {
    if (!path.extname(pathname)) file = path.join(root, '200.html')
  }
  let stat
  try { stat = fs.statSync(file); if (!stat.isFile()) throw new Error('not file') }
  catch { response.writeHead(404, { 'content-type': 'text/plain', 'cache-control': 'no-store' }).end('Not found'); return }
  const extension = path.extname(file).toLowerCase()
  const cache = extension === '.html' ? 'no-store'
    : pathname.startsWith('/_nuxt/') ? 'public, max-age=31536000, immutable'
      : pathname.startsWith('/native/') ? 'public, max-age=60' : 'public, max-age=3600'
  response.writeHead(200, {
    'content-type': types[extension] ?? 'application/octet-stream',
    'content-length': stat.size, 'cache-control': cache, 'access-control-allow-origin': '*',
    'timing-allow-origin': '*', 'x-yunle-local-preview': 'native-game-discovery',
    ...(faultFile && extension === '.html' ? { 'content-security-policy': "default-src 'self' data: blob:; script-src 'self' 'unsafe-inline' 'unsafe-eval' blob:; worker-src 'self' blob:; connect-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; font-src 'self' data:; media-src 'self' data: blob:" } : {}),
  })
  if (request.method === 'HEAD') { response.end(); return }
  fs.createReadStream(file).on('error', () => response.destroy()).pipe(response)
})
server.listen(port, '127.0.0.1', () => {
  fs.writeFileSync('/tmp/yunle-native-games.uGZuY9/preview-server.pid', String(process.pid) + '\n')
  process.stdout.write(JSON.stringify({ pid: process.pid, port, root, owner: 'native-game-discovery', cleanup: 'root finishes simulator validation' }) + '\n')
})
function stop() { server.close(() => process.exit(0)); setTimeout(() => process.exit(0), 2000).unref() }
process.on('SIGTERM', stop)
process.on('SIGINT', stop)

